def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not coeffs:
        return "0"

    parts = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine the sign
        if not parts:
            # First term: no leading +
            if coeff < 0:
                sign = "-"
            else:
                sign = ""
        else:
            # Subsequent terms
            if coeff < 0:
                sign = "-"
            else:
                sign = "+"

        abs_coeff = abs(coeff)

        # Determine the coefficient part
        if degree > 0 and abs_coeff == 1:
            coeff_part = ""
        else:
            coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree == 0:
            var_part = ""
        elif degree == 1:
            var_part = "x"
        else:
            var_part = f"x^{degree}"

        term = f"{sign}{coeff_part}{var_part}"
        parts.append(term)

    if not parts:
        return "0"

    return "".join(parts)

