def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort applicants by score descending, then by registration number ascending
    from typing import List, Tuple
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Calculate the cutoff index: 150% of m, rounded down
    # The number of top applicants to consider is floor(1.5 * m)
    cutoff_index = int(1.5 * m)

    # Handle edge case where cutoff_index exceeds the number of applicants
    if cutoff_index > n:
        cutoff_index = n

    # If cutoff_index is 0, no applicants qualify (but this shouldn't happen with reasonable m)
    if cutoff_index == 0:
        return (0, [])

    # The score of the applicant at the cutoff_index-th position (1-based) is the cutoff
    # That is, the score of sorted_applicants[cutoff_index - 1]
    cutoff_score = sorted_applicants[cutoff_index - 1][1]

    # Collect all applicants with score >= cutoff_score
    # They should be returned in the same sorted order (score desc, reg num asc)
    qualified = []
    for applicant in sorted_applicants:
        if applicant[1] >= cutoff_score:
            qualified.append(applicant)

    return (cutoff_score, qualified)

